"""
SQL Analyst Agent - Responsible for translating business requests into database queries.
"""

from typing import Any
from ..tools.database_tool import run_database_query


class SQLAnalystAgent:
    def __init__(self, agent_id: str = "sql-analyst-agent") -> None:
        self.agent_id = agent_id

    def execute_query_task(self, sql_query: str, client_mode: str = "guarded") -> dict[str, Any]:
        """Executes a SQL query task generated by the LLM reasoning loop."""
        return run_database_query(
            query=sql_query,
            client_mode=client_mode,
            agent_id=self.agent_id,
        )

